{
  "status": "SUPPORTED",
  "task_summary": "Find a fastener and tool, use them to secure the yellow object on the table, then put the tool back on the table.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "workpiece",
        "entity_kind": "OBJECT",
        "function": "The object on the table that needs to be secured.",
        "required_count": 1
      ,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["yellow block", "assembly"],
        "required_properties": ["needs fastening"]
      },
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "The component used to join the workpiece.",
        "required_count": 1
      ,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screw", "bolt", "clip", "pin"],
        "required_properties": ["compatible with workpiece"]
      },
      {
        "id": "tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to apply the fastener.",
        "required_count": 1
      ,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "pliers"],
        "required_properties": ["capable of manipulation"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the task occurs and tools are stored.",
        "required_count": 1
      ,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk"],
        "required_properties": ["flat surface"]
      }
    ],
    "functional_relations": [
      {
        "id": "fastening_pair",
        "relation": "compatible_with",
        "participant_roles": ["workpiece", "fastener"],
        "required": true
      },
      {
        "id": "equipment_placement",
        "relation": "rests_on",
        "participant_roles": ["tool", "workbench"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "apply_fastener",
        "operation": "fastening",
        "participant_roles": ["workpiece", "fastener", "tool"],
        "operation_count": 1
      },
      {
        "id": "store_equipment",
        "operation": "placing",
        "participant_roles": ["tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "workpiece": [
        {
          "label": "yellow object on tray",
          "visual_description": "A yellow rectangular block sitting on a black tray on the wooden table."
        }
      ],
      "fastener": [],
      "tool": []
    },
    "inspectable_regions": [
      {
        "id": "back_cabinet",
        "label": "Grey cabinet",
        "visual_description": "A tall grey cabinet standing against the wall behind the table with a white handle.",
        "reason": "Likely contains tools or hardware."
      },
      {
        "id": "left_drawer",
        "label": "Left drawer",
        "visual_description": "A blue drawer under the left side of the table with a white handle.",
        "reason": "Likely contains small tools or hardware."
      },
      {
        "id": "right_drawer",
        "label": "Right drawer",
        "visual_description": "A blue drawer under the right side of the table with a white handle.",
        "reason": "Likely contains small tools or hardware."
      }
    ],
    "inspection_order": [
      "back_cabinet",
      "left_drawer",
      "right_drawer"
    ]
  }
  ,
